insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values
('40000000-0000-4000-8000-000000000028','$\\sen(x^2)+C$','Use $u=x^2$; o diferencial $du=2x\\,dx$ aparece inteiro.'),('40000000-0000-4000-8000-000000000029','$e^{x^3}+C$','Use $u=x^3$ e $du=3x^2\\,dx$.'),('40000000-0000-4000-8000-000000000030','$\\frac12\\ln(x^2+4)+C$','A derivada interna é $2x$, então o fator $1/2$ é necessário.'),('40000000-0000-4000-8000-000000000031','$\\ln2$','A substituição transforma os limites em 1 e 2.'),('40000000-0000-4000-8000-000000000032','$u=x^2+9$','Sua derivada é $2x$, proporcional ao fator externo.'),('40000000-0000-4000-8000-000000000033','$-1/[3(3x^2+5)]+C$','Ajuste o diferencial antes de integrar $u^{-2}$.'),('40000000-0000-4000-8000-000000000034','$\\frac12\\ln(7/4)$','Converta os limites: $u$ vai de 4 a 7.'),('40000000-0000-4000-8000-000000000035','$\\frac14\\sen(x^4)+C$','A derivada de $x^4$ é $4x^3$, exigindo o fator $1/4$.')
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values
('70000000-0000-4000-8000-000000000044','40000000-0000-4000-8000-000000000028','Substitua','$u=x^2$, $du=2x\\,dx$; então $\\int\\cos u\\,du=\\sen u+C$.',1),('70000000-0000-4000-8000-000000000045','40000000-0000-4000-8000-000000000029','Substitua','$u=x^3$, então a integral é $\\int e^u\\,du=e^u+C$.',1),('70000000-0000-4000-8000-000000000046','40000000-0000-4000-8000-000000000030','Ajuste o diferencial','$x\\,dx=du/2$, logo a integral é $\\frac12\\int du/u$.',1),('70000000-0000-4000-8000-000000000047','40000000-0000-4000-8000-000000000031','Troque os limites','$u=x^2+1$ leva 0 a 1 e 1 a 2; $\\int_1^2du/u=\\ln2$.',1),('70000000-0000-4000-8000-000000000048','40000000-0000-4000-8000-000000000032','Observe a expressão interna','$u=x^2+9$ deixa $x\\,dx=du/2$.',1),('70000000-0000-4000-8000-000000000049','40000000-0000-4000-8000-000000000033','Integre em $u$','$u=3x^2+5$, $du=6x\\,dx$ e $\\int u^{-2}du=-u^{-1}$.',1),('70000000-0000-4000-8000-000000000050','40000000-0000-4000-8000-000000000034','Ajuste e avalie','$x\\,dx=du/2$; então $\\frac12[\\ln u]_4^7=\\frac12\\ln(7/4)$.',1),('70000000-0000-4000-8000-000000000051','40000000-0000-4000-8000-000000000035','Compense o 4','$u=x^4$, $x^3dx=du/4$, logo $\\frac14\\int\\cos u\\,du$.',1)
